/* 等价 C 语言参考：银行家算法安全性检查（示意） */
#include <stdio.h>
#include <stdbool.h>

#define MAXN 16
#define MAXM 16

/* available[0..m-1]；max_need / allocation 为 [n][m]；seq 输出安全序列；返回进程数 */
int safety(int n, int m, int available[], int max_need[][MAXM],
           int allocation[][MAXM], int seq[]) {
    int work[MAXM];
    int need[MAXN][MAXM];
    bool finish[MAXN];
    for (int j = 0; j < m; j++) work[j] = available[j];
    for (int i = 0; i < n; i++) {
        finish[i] = false;
        for (int j = 0; j < m; j++) need[i][j] = max_need[i][j] - allocation[i][j];
    }

    int cnt = 0;
    while (true) {
        int found = -1;
        for (int i = 0; i < n && found == -1; i++) {
            if (finish[i]) continue;
            bool ok = true;
            for (int j = 0; j < m; j++) {
                if (need[i][j] > work[j]) { ok = false; break; }
            }
            if (ok) found = i;   /* 取最小下标 */
        }
        if (found == -1) break;
        for (int j = 0; j < m; j++) work[j] += allocation[found][j];
        finish[found] = true;
        seq[cnt++] = found;
    }
    return cnt;   /* cnt == n 表示安全 */
}

int main(void) {
    int available[3] = {3, 3, 2};
    int max_need[5][MAXM] = {{7,5,3},{3,2,2},{9,0,2},{2,2,2},{4,3,3}};
    int allocation[5][MAXM] = {{0,1,0},{2,0,0},{3,0,2},{2,1,1},{0,0,2}};
    int seq[5];
    int cnt = safety(5, 3, available, max_need, allocation, seq);
    printf("safe=%d seq=", cnt == 5);
    for (int i = 0; i < cnt; i++) printf("%d ", seq[i]);
    printf("\n");
    return 0;
}
